10	// newTestGroupCache creates a RegistryGroupCache backed by a temp dir.
11	func newTestGroupCache(t *testing.T) *RegistryGroupCache {
12		t.Helper()
13		return &RegistryGroupCache{
14			path:    filepath.Join(t.TempDir(), "registry-groups.json"),
15			entries: make(map[string]RegistryGroupEntry),
16		}
17	}
18	
19	func groupEntry(at time.Time, aliases ...string) RegistryGroupEntry {
20		members := make([]RegistryGroupMember, 0, len(aliases))
21		for _, a := range aliases {
22			members = append(members, RegistryGroupMember{Alias: a, URL: "https://nexus.example.com/repository/" + a})
23		}
24		return RegistryGroupEntry{Members: members, DiscoveredAt: at}
25	}
