33	func TestGroupCache_SetAndGet(t *testing.T) {
34		c := newTestGroupCache(t)
35		at := time.Now().Truncate(time.Second)
36	
37		if err := c.Set("prod", groupEntry(at, "hosted", "dhi")); err != nil {
38			t.Fatalf("Set: %v", err)
39		}
40	
41		entry := c.Get("prod")
42		if entry == nil {
43			t.Fatal("Get returned nothing for a slug just set")
44		}
45		if len(entry.Members) != 2 {
46			t.Errorf("Members = %+v, want both", entry.Members)
47		}
48		if entry.Members[0].Alias != "hosted" {
49			t.Errorf("Members[0].Alias = %q, want the order preserved", entry.Members[0].Alias)
50		}
51		if !entry.DiscoveredAt.Equal(at) {
52			t.Errorf("DiscoveredAt = %v, want %v — the column reads it", entry.DiscoveredAt, at)
53		}
54	}
