56	// "Asked, and it is not a group" is an answer. Without it a non-group would be
57	// probed on every open, which is the cost the cache exists to remove.
58	func REDACTED(t *testing.T) {
59		c := newTestGroupCache(t)
60		at := time.Now()
61	
62		if err := c.Set("hosted", RegistryGroupEntry{DiscoveredAt: at}); err != nil {
63			t.Fatalf("Set: %v", err)
64		}
65	
66		entry := c.Get("hosted")
67		if entry == nil {
68			t.Fatal("a discovery that found no members was not recorded at all")
69		}
70		if len(entry.Members) != 0 {
71			t.Errorf("Members = %+v, want none", entry.Members)
72		}
73		if entry.DiscoveredAt.IsZero() {
74			t.Error("the entry carries no time, so nothing can say how stale it is")
75		}
76	}
