78	func TestGroupCache_Overwrite(t *testing.T) {
79		c := newTestGroupCache(t)
80		_ = c.Set("prod", groupEntry(time.Now().Add(-time.Hour), "old"))
81	
82		newer := time.Now()
83		if err := c.Set("prod", groupEntry(newer, "a", "b", "c")); err != nil {
84			t.Fatalf("Set: %v", err)
85		}
86	
87		entry := c.Get("prod")
88		if len(entry.Members) != 3 {
89			t.Errorf("Members = %+v, want the refreshed list to replace the old one", entry.Members)
90		}
91		if !entry.DiscoveredAt.Equal(newer) {
92			t.Errorf("DiscoveredAt = %v, want the refresh time", entry.DiscoveredAt)
93		}
94	}
