96	func TestGroupCache_GetAllCopies(t *testing.T) {
97		c := newTestGroupCache(t)
98		_ = c.Set("a", groupEntry(time.Now(), "one"))
99		_ = c.Set("b", groupEntry(time.Now(), "two"))
100	
101		all := c.GetAll()
102		if len(all) != 2 {
103			t.Fatalf("GetAll returned %d entries, want 2", len(all))
104		}
