127	// hashedResultName is how both result stores name a file: the SHA256 of the
128	// target, because a Docker reference and an absolute path both carry characters
129	// a filename cannot. It is written here as well as in the two Save paths, and
130	// TestTheReadOnlyResultPathMatchesTheWrittenOne holds the two in step — the
131	// alternative was exporting a path helper from each, which is three names for
132	// one rule.
133	func hashedResultName(target string) string {
134		return fmt.Sprintf("%x.json", sha256.Sum256([]byte(target)))
135	}
