137	func readScanResult(path string) (*scan.Result, error) {
138		data, err := os.ReadFile(path)
139		if err != nil {
140			return nil, err
141		}
142		var result scan.Result
143		if err := json.Unmarshal(data, &result); err != nil {
144			return nil, err
145		}
146		return &result, nil
147	}
