149	// ReadRegistryGroups returns every group discovery on disk, without writing.
150	//
151	// An absent slug and a slug whose entry holds no members are different answers:
152	// the first means nobody has asked this registry whether it is a group, the
153	// second means somebody asked and it is not (§3.8, decision 3). Both come back
154	// here as they are stored, and the caller keeps them apart.
155	func ReadRegistryGroups() (map[string]RegistryGroupEntry, error) {
156		dir, err := scanCacheDir()
157		if err != nil {
158			return nil, err
159		}
160		return readRegistryGroupsAt(filepath.Join(dir, "registry-groups.json"))
161	}
162	
163	func readRegistryGroupsAt(path string) (map[string]RegistryGroupEntry, error) {
164		entries := map[string]RegistryGroupEntry{}
165		data, err := os.ReadFile(path)
166		if err != nil {
167			// A cache that does not exist yet is empty, not an error.
168			return entries, nil
169		}
170		if err := json.Unmarshal(data, &entries); err != nil {
171			return nil, err
172		}
173		return entries, nil
174	}
